// Lava lamp — warm metaballs rising slowly over a lit background.
uniform vec3  uBlob;        // @param #FF5A1F
uniform vec3  uBackground;  // @param #1C0716
uniform float uSpeed;       // @param 0.3 0 2
uniform float uSize;        // @param 1.0 0.5 1.8

void main() {
  float asp = iResolution.x / iResolution.y;
  vec2 p = (uv - 0.5) * vec2(asp, 1.0);
  float t = iTime * uSpeed;

  // Gentle wobble of the whole wax so blobs don't look rigid.
  vec2 q = p + 0.03 * vec2(noise(p * 3.0 + t * 0.5) - 0.5, noise(p * 3.0 - t * 0.4 + 7.0) - 0.5);

  float field = 0.0;
  for (int i = 0; i < 9; i++) {
    float fi = float(i);
    float h  = hash1(fi + 1.37);
    float h2 = hash1(fi * 3.71 + 0.53);
    float r  = (0.09 + 0.08 * h2) * uSize;
    // Slow upward travel; spawn/despawn happens off-screen.
    float cyc = fract(t * (0.05 + 0.045 * h) + h2);
    float y = mix(-0.5 - r * 2.2, 0.5 + r * 2.2, cyc);
    float x = (h - 0.5) * asp * 0.75 + 0.07 * sin(t * 0.6 + fi * 2.1 + y * 2.5);
    vec2 d = q - vec2(x, y);
    d *= vec2(1.0 + 0.12 * sin(t * 0.9 + fi), 1.0 - 0.1 * sin(t * 0.9 + fi)); // squash/stretch
    field += r * r / (dot(d, d) + 1e-4);
  }
  // Molten pool at the bottom and a thin cap at the top, like a real lamp.
  float pool = q.y + 0.5 + 0.02 * sin(q.x * 9.0 + t * 1.3);
  field += 0.010 / max(pool * pool, 1e-4) * 0.5 + 0.004 / max(pow(0.52 - q.y, 2.0), 1e-4) * 0.3;

  float w = max(fwidth(field), 0.01);
  float m = smoothstep(1.0 - w, 1.0 + w, field);

  // Background: warmer near the bulb at the bottom, glow halo around wax.
  vec3 bg = uBackground * (1.25 - 0.65 * uv.y);
  bg += uBlob * 0.28 * smoothstep(0.25, 1.0, field) * (1.0 - m);
  bg += uBlob * 0.12 * exp(-6.0 * (uv.y)) ;

  // Wax shading: dark rim, hot luminous core, soft specular.
  float inner = clamp((field - 1.0) / 2.5, 0.0, 1.0);
  vec3 wax = uBlob * (0.55 + 0.75 * sqrt(inner));
  wax = mix(wax, vec3(1.0, 0.86, 0.55), 0.3 * inner * inner);
  wax += 0.08 * smoothstep(0.0, 0.5, inner) * (0.5 - uv.y + 0.5) * uBlob;

  vec3 col = mix(bg, wax, m);
  float vig = 1.0 - 0.55 * dot(p * vec2(0.8, 1.0), p * vec2(0.8, 1.0));
  col *= vig;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
